      toolbox: { title: '开发工具箱', icon: 'toolbox', hint: '本地执行、数据不出浏览器的高频工具' },
      collab: { title: '研发协作', icon: 'git', hint: '仓库分支与改动、Docker 容器，全部只读探测' },
      knowledge: { title: '知识空间', icon: 'book', hint: '收藏、笔记与排障记录' },
